def copy_related_records_to_relations(apps, schema_editor):
    """Records already linked with the old "related records" list become typed 'related' links."""
    Record = apps.get_model('records', 'Record')
    RecordRelation = apps.get_model('records', 'RecordRelation')
    Through = Record.related_records.through
    seen = set()
